class WorkforcePlanningController extends Controller{
public function references(Request$r):JsonResponse{$a=$this->actor($r);$units=DB::table('hr_organization_units')->where('company_id',$a->company_id)->where('status','active')->where(fn($q)=>$q->whereNull('effective_until')->orWhereDate('effective_until','>=',now()))->select(['id','code','name','unit_type'])->orderBy('name')->get();$positions=DB::table('hr_positions')->where('company_id',$a->company_id)->where(fn($q)=>$q->whereNull('effective_until')->orWhereDate('effective_until','>=',now()))->select(['id','organization_unit_id','position_number','title','status'])->orderBy('title')->get();$locations=DB::table('hr_employment_assignments')->where('company_id',$a->company_id)->whereNotNull('location_code')->distinct()->orderBy('location_code')->pluck('location_code');$staffTypes=DB::table('staff')->where('company_id',$a->company_id)->whereNull('employment_ended_at')->whereNotNull('staff_type')->distinct()->orderBy('staff_type')->pluck('staff_type');return response()->json(['status'=>'success','data'=>['organization_units'=>$units,'positions'=>$positions,'location_codes'=>$locations,'staff_types'=>$staffTypes]]);}
public function index(Request$r):JsonResponse{$a=$this->actor($r);return response()->json(['status'=>'success','data'=>DB::table('hr_workforce_plan_versions')->where('company_id',$a->company_id)->select(['id','code','version','name','baseline_as_of','horizon_start','horizon_end','currency','status','plan_checksum','approved_at'])->orderByDesc('horizon_start')->paginate($r->integer('per_page',50))]);}
public function show(Request$r,string$id):JsonResponse{$a=$this->actor($r);$p=DB::table('hr_workforce_plan_versions')->where('id',$id)->where('company_id',$a->company_id)->first();abort_unless($p,404);return response()->json(['status'=>'success','data'=>['plan'=>$p,'lines'=>DB::table('hr_workforce_plan_lines')->where('plan_version_id',$id)->orderBy('period_start')->get(),'snapshots'=>DB::table('hr_workforce_plan_snapshots')->where('plan_version_id',$id)->latest('generated_at')->get()]]);}
public function store(Request$r):JsonResponse{$this->enabled();$a=$this->actor($r);$d=$r->validate(['code'=>['required','string','max:80'],'version'=>['required','integer','min:1'],'name'=>['required','string','max:255'],'baseline_as_of'=>['required','date','before_or_equal:horizon_start'],'horizon_start'=>['required','date'],'horizon_end'=>['required','date','after_or_equal:horizon_start'],'currency'=>['nullable','string','size:3','regex:/^[A-Za-z]{3}$/'],'assumptions'=>['required','array'],'lines'=>['required','array','min:1','max:1000'],'lines.*.organization_unit_id'=>['nullable','uuid'],'lines.*.position_id'=>['nullable','uuid'],'lines.*.location_code'=>['nullable','string','max:80'],'lines.*.staff_type'=>['nullable','string','max:80'],'lines.*.period_start'=>['required','date'],'lines.*.period_end'=>['required','date'],'lines.*.planned_fte'=>['required','numeric','min:0'],'lines.*.planned_headcount'=>['required','integer','min:0'],'lines.*.planned_cost'=>['nullable','numeric','min:0'],'lines.*.rationale'=>['required','string','max:5000'],'lines.*.assumption_overrides'=>['nullable','array']]);$d['currency']=isset($d['currency'])?strtoupper($d['currency']):null;$seen=[];foreach($d['lines']as$line){abort_unless((float)$line['planned_fte']<=(int)$line['planned_headcount'],422,'Planned FTE cannot exceed planned headcount.');abort_if(isset($line['planned_cost'])&&!$d['currency'],422,'A plan currency is required when any line contains planned cost.');$scope=implode('|',[$line['organization_unit_id']??'', $line['position_id']??'', $line['location_code']??'', $line['staff_type']??'', $line['period_start'], $line['period_end']]);abort_if(isset($seen[$scope]),422,'Duplicate plan scope and period lines are not allowed.');$seen[$scope]=true;}return DB::transaction(function()use($r,$a,$d){$id=(string)Str::uuid();DB::table('hr_workforce_plan_versions')->insert(['id'=>$id,'company_id'=>$a->company_id,'code'=>$d['code'],'version'=>$d['version'],'name'=>$d['name'],'baseline_as_of'=>$d['baseline_as_of'],'horizon_start'=>$d['horizon_start'],'horizon_end'=>$d['horizon_end'],'currency'=>$d['currency']??null,'assumptions'=>json_encode($d['assumptions'],JSON_THROW_ON_ERROR),'status'=>'draft','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);foreach($d['lines']as$line){abort_unless($line['period_start']>=$d['horizon_start']&&$line['period_end']<=$d['horizon_end']&&$line['period_end']>=$line['period_start'],422,'Plan lines must stay inside the horizon.');foreach(['organization_unit_id'=>'hr_organization_units','position_id'=>'hr_positions']as$f=>$table)if(!empty($line[$f]))abort_unless(DB::table($table)->where('id',$line[$f])->where('company_id',$a->company_id)->exists(),422,'Plan references must share one legal entity.');$line['assumption_overrides']=isset($line['assumption_overrides'])?json_encode($line['assumption_overrides'],JSON_THROW_ON_ERROR):null;DB::table('hr_workforce_plan_lines')->insert($line+['id'=>(string)Str::uuid(),'plan_version_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);}return response()->json(['status'=>'success','data'=>DB::table('hr_workforce_plan_versions')->find($id)],201);});}
public function submit(Request$r,string$id):JsonResponse{$this->enabled();$a=$this->actor($r);return DB::transaction(function()use($r,$a,$id){$p=DB::table('hr_workforce_plan_versions')->where('id',$id)->where('company_id',$a->company_id)->lockForUpdate()->first();abort_unless($p,404);abort_unless($p->status==='draft',409);$payload=$this->payload($p);$checksum=hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));DB::table('hr_workforce_plan_versions')->where('id',$id)->update(['status'=>'pending_approval','plan_checksum'=>$checksum,'submitted_by'=>$r->user()->id,'submitted_at'=>now(),'updated_at'=>now()]);$this->event($id,'submitted','draft','pending_approval','Submitted for independent approval.',$checksum,$r->user()->id);return response()->json(['status'=>'success','data'=>DB::table('hr_workforce_plan_versions')->find($id)]);});}
public function decide(Request$r,string$id):JsonResponse{$this->enabled();$a=$this->actor($r);$d=$r->validate(['decision'=>['required','in:approved,rejected'],'reason'=>['required','string','max:3000']]);return DB::transaction(function()use($r,$a,$id,$d){$p=DB::table('hr_workforce_plan_versions')->where('id',$id)->where('company_id',$a->company_id)->lockForUpdate()->first();abort_unless($p,404);abort_unless($p->status==='pending_approval',409);abort_if($p->submitted_by===$r->user()->id,409,'Plan submitter cannot approve the same version.');$checksum=hash('sha256',json_encode($this->payload($p),JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));abort_unless(hash_equals($p->plan_checksum,$checksum),409,'Plan content changed after submission.');DB::table('hr_workforce_plan_versions')->where('id',$id)->update(['status'=>$d['decision'],'approved_by'=>$r->user()->id,'approved_at'=>now(),'decision_reason'=>$d['reason'],'updated_at'=>now()]);$this->event($id,$d['decision'],'pending_approval',$d['decision'],$d['reason'],$checksum,$r->user()->id);return response()->json(['status'=>'success','data'=>DB::table('hr_workforce_plan_versions')->find($id)]);});}
public function snapshot(Request$r,string$id):JsonResponse{$this->enabled();$a=$this->actor($r);$d=$r->validate(['as_of_date'=>['required','date']]);$p=DB::table('hr_workforce_plan_versions')->where('id',$id)->where('company_id',$a->company_id)->where('status','approved')->first();abort_unless($p,404);abort_unless($d['as_of_date']>=$p->horizon_start&&$d['as_of_date']<=$p->horizon_end,422,'Snapshot date must be inside the approved horizon.');$lines=DB::table('hr_workforce_plan_lines')->where('plan_version_id',$id)->whereDate('period_start','<=',$d['as_of_date'])->whereDate('period_end','>=',$d['as_of_date'])->get();$actuals=[];$variances=[];$sources=[];foreach($lines as$line){$q=DB::table('hr_employment_assignments')->where('company_id',$a->company_id)->whereDate('effective_from','<=',$d['as_of_date'])->where(fn($x)=>$x->whereNull('effective_until')->orWhereDate('effective_until','>=',$d['as_of_date']));if($line->organization_unit_id)$q->where('organization_unit_id',$line->organization_unit_id);if($line->position_id)$q->where('position_id',$line->position_id);if($line->location_code)$q->where('location_code',$line->location_code);if($line->staff_type)$q->whereIn('staff_id',DB::table('staff')->select('id')->where('company_id',$a->company_id)->where('staff_type',$line->staff_type));$rows=$q->select(['id','staff_id','updated_at'])->get()->unique('staff_id');$actual=$rows->count();$actuals[$line->id]=['actual_headcount'=>$actual,'actual_fte'=>null,'fte_actual_unavailable'=>true,'cost_actual_unavailable'=>true];$variances[$line->id]=['headcount_variance'=>$actual-(int)$line->planned_headcount,'fte_variance'=>null,'cost_variance'=>null];foreach($rows as$row)$sources[]=['line_id'=>$line->id,'assignment_id'=>$row->id,'updated_at'=>(string)$row->updated_at];}usort($sources,fn($x,$y)=>strcmp($x['line_id'].$x['assignment_id'],$y['line_id'].$y['assignment_id']));$sourceChecksum=hash('sha256',json_encode(['plan_checksum'=>$p->plan_checksum,'as_of'=>$d['as_of_date'],'sources'=>$sources],JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));$existing=DB::table('hr_workforce_plan_snapshots')->where('plan_version_id',$id)->where('as_of_date',$d['as_of_date'])->where('source_checksum',$sourceChecksum)->first();if($existing)return response()->json(['status'=>'success','data'=>$existing,'idempotent_replay'=>true]);$payload=['actuals'=>$actuals,'variances'=>$variances];$sid=(string)Str::uuid();DB::table('hr_workforce_plan_snapshots')->insert(['id'=>$sid,'company_id'=>$a->company_id,'plan_version_id'=>$id,'as_of_date'=>$d['as_of_date'],'cutoff_at'=>now(),'actual_payload'=>json_encode($actuals,JSON_THROW_ON_ERROR),'variance_payload'=>json_encode($variances,JSON_THROW_ON_ERROR),'source_checksum'=>$sourceChecksum,'snapshot_checksum'=>hash('sha256',json_encode($payload+['source_checksum'=>$sourceChecksum],JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)),'generated_by'=>$r->user()->id,'generated_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);return response()->json(['status'=>'success','data'=>DB::table('hr_workforce_plan_snapshots')->find($sid)],201);}
private function payload(object$p):array{return['plan'=>collect((array)$p)->except(['status','plan_checksum','submitted_by','submitted_at','approved_by','approved_at','decision_reason','created_at','updated_at'])->all(),'lines'=>DB::table('hr_workforce_plan_lines')->where('plan_version_id',$p->id)->orderBy('id')->get()->map(fn($x)=>collect((array)$x)->except(['created_at','updated_at'])->all())->all()];}private function event(string$id,string$type,?string$from,string$to,string$reason,string$checksum,string$actor):void{DB::table('hr_workforce_plan_events')->insert(['id'=>(string)Str::uuid(),'plan_version_id'=>$id,'event_type'=>$type,'from_status'=>$from,'to_status'=>$to,'reason'=>$reason,'plan_checksum'=>$checksum,'actor_user_id'=>$actor,'occurred_at'=>now()]);}private function actor(Request$r):Staff{return Staff::query()->where('user_id',$r->user()->id)->firstOrFail();}private function enabled():void{abort_unless(config('hr.features.engagement_analytics',false),409,'HR engagement and analytics writes are not enabled.');}}
